import { useState, useEffect, useCallback } from 'react';
import { Card, ConfigProvider, Layout, theme, Spin, message } from 'antd';
import enUS from 'antd/locale/en_US';
import 'dayjs/locale/en';
import useAuthStore from './stores/authStore';
import useFacilityStore from './stores/facilityStore';
import useRealtimeStore from './stores/realtimeStore';
import AppLayout from './components/AppLayout';
import UnauthorizedPage from './components/UnauthorizedPage';
import CompanyPermissionRequired from './components/CompanyPermissionRequired';
import ExecutiveDashboard from './components/ExecutiveDashboard';
import EmployeeListView from './components/modules/employees/EmployeeListView';
import ERPNextAssetsListView from './components/modules/assets/ERPNextAssetsListView';
import AssetDetailView from './components/modules/assets/AssetDetailView';
import AssetCreateForm from './components/modules/assets/AssetCreateForm';
import FacilitiesListView from './components/modules/facilities/FacilitiesListView';
import FacilityOnboardingWizard from './components/modules/facilities/FacilityOnboardingWizard';
import AffiliationsListView from './components/modules/affiliations/AffiliationsListView';
import LicensesListView from './components/modules/licenses/LicensesListView';
import LicenseDetailView from './components/modules/licenses/LicenseDetailView';
import EmptyState from './components/shared/EmptyState/EmptyState';
import BulkUploadListPage from './pages/affiliations/BulkUploadListPage';
import BulkUploadPage from './pages/affiliations/BulkUploadPage';
import BulkUploadDetailView from './pages/affiliations/BulkUploadDetailView';
import SingleAffiliationPage from './pages/affiliations/SingleAffiliationPage';
import UserManagementPage from './pages/user-management/UserManagementPage';
import UserListPage from './pages/user-management/UserListPage';
import CreateUserPage from './pages/user-management/CreateUserPage';
import EditUserPage from './pages/user-management/EditUserPage';
import OidcAppsView from './components/modules/administration/OidcAppsView';
import ProfilePage from './pages/profile/ProfilePage';
import LeaveApplicationsListView from './components/modules/hr/LeaveApplicationsListView';
import ShiftManagementView from './components/modules/hr/ShiftManagementView';
import ClaimsListView from './components/modules/claims/ClaimsListView';
import RecruitmentDeskPage from './components/modules/recruitment/RecruitmentDeskPage';
import JobPostEditorPage from './components/modules/recruitment/JobPostEditorPage';
import CandidateProfileView from './components/modules/recruitment/CandidateProfileView';
import { getCsrfToken, setCsrfToken } from './utils/csrf';
import { COMPANY_PERMISSION_ROUTE, getAccessPolicy, isRouteAllowed } from './access/accessPolicy';
import './App.css';

const { Content } = Layout;
const DEFAULT_FAVICON = '/assets/careverse_hq/images/favicon.svg?v=20260215b';
const ROUTE_FAVICONS: Record<string, string> = {
  licenses: DEFAULT_FAVICON,
  affiliations: DEFAULT_FAVICON,
};
const ENABLE_USER_MGMT_REFACTOR = import.meta.env.VITE_ENABLE_USER_MGMT_REFACTOR !== 'false';
const ENABLE_FACILITY_ONBOARDING = import.meta.env.VITE_ENABLE_FACILITY_ONBOARDING !== 'false';

const decodeHashSegment = (segment: string): string => {
  try {
    return decodeURIComponent(segment);
  } catch {
    return segment;
  }
};

const encodeHashId = (value: string): string => (
  value
    .split('/')
    .map((segment) => encodeURIComponent(segment))
    .join('/')
);

function App() {
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [currentRoute, setCurrentRoute] = useState('dashboard');
  const [currentDetailId, setCurrentDetailId] = useState<string | null>(null);
  const [initializing, setInitializing] = useState(true);

  // Zustand auth store
  const {
    isAuthenticated,
    loading: authLoading,
    checkAuthentication
  } = useAuthStore();

  // Zustand facility store
  const {
    accessMode,
    loadCompanyAndFacilities,
    loading: facilityLoading,
  } = useFacilityStore();
  const accessPolicy = getAccessPolicy(accessMode);

  // Zustand realtime store
  const {
    initialize: initializeRealtime,
    disconnect: disconnectRealtime,
  } = useRealtimeStore();

  // Initialize CSRF token from window object (injected by Frappe)
  useEffect(() => {
    const win = window as Window & {
      csrf_token?: string;
      frappe?: { boot?: { csrf_token?: string } };
    };

    if (!win.csrf_token && win.frappe?.boot?.csrf_token) {
      setCsrfToken(win.frappe.boot.csrf_token);
    }

    if (!getCsrfToken()) {
      console.error('[SECURITY] CSRF token is not available. Frappe may not have injected it properly.');
    } else {
      console.log('[SECURITY] CSRF token initialized successfully');
    }
  }, []);

  // Listen for session expiry events
  useEffect(() => {
    const handleSessionExpired = () => {
      console.warn('[SECURITY] Session expired event received. Triggering re-authentication.');
      checkAuthentication();
    };

    window.addEventListener('session-expired', handleSessionExpired);
    return () => {
      window.removeEventListener('session-expired', handleSessionExpired);
    };
  }, [checkAuthentication]);

  // Dev-only toast for CSRF refresh attempts/success.
  useEffect(() => {
    if (!import.meta.env.DEV) return;

    const onCsrfRefresh = (event: Event) => {
      const detail = (event as CustomEvent<{ phase?: string }>).detail;
      if (detail?.phase === 'success') {
        message.info('[DEV] CSRF token refreshed');
      } else if (detail?.phase === 'fallback') {
        message.warning('[DEV] CSRF refresh fallback used');
      }
    };

    window.addEventListener('csrf-refresh', onCsrfRefresh as EventListener);
    return () => window.removeEventListener('csrf-refresh', onCsrfRefresh as EventListener);
  }, []);

  // Initialize app: authenticate first, then resolve access mode from the server
  useEffect(() => {
    let isSubscribed = true;

    const initialize = async () => {
      console.log('[App] Starting optimized initialization flow...');

      const authPromise = checkAuthentication();
      const isAuth = await authPromise;

      if (!isSubscribed) return;

      if (isAuth) {
        await loadCompanyAndFacilities();
        if (isSubscribed) setInitializing(false);
      } else {
        console.log('[App] User not authenticated');
        if (isSubscribed) setInitializing(false);
      }
    };

    initialize();

    return () => {
      isSubscribed = false;
    };
  }, [checkAuthentication, loadCompanyAndFacilities]);

  // Initialize realtime connection when authenticated and has company permission
  useEffect(() => {
    if (!initializing && isAuthenticated && accessPolicy.canUseRealtime && !facilityLoading) {
      console.log('[App] Initializing realtime connection...');
      initializeRealtime();
    }
  }, [initializing, isAuthenticated, accessPolicy.canUseRealtime, facilityLoading, initializeRealtime]);

  // Cleanup realtime on page unload
  useEffect(() => {
    const handleBeforeUnload = () => {
      console.log('[App] Page unloading, disconnecting realtime...');
      disconnectRealtime();
    };

    window.addEventListener('beforeunload', handleBeforeUnload);
    return () => {
      window.removeEventListener('beforeunload', handleBeforeUnload);
    };
  }, [disconnectRealtime]);

  // Update document theme attribute when dark mode changes
  useEffect(() => {
    document.documentElement.setAttribute('data-theme', isDarkMode ? 'dark' : 'light');
  }, [isDarkMode]);

  // Keep browser-tab favicon in sync with route.
  // Affiliations intentionally shares the same favicon as Licenses.
  useEffect(() => {
    const routeKey = currentRoute === 'licenses' || currentRoute.startsWith('licenses/')
      ? 'licenses'
      : currentRoute === 'affiliations' || currentRoute.startsWith('affiliations/')
        ? 'affiliations'
        : currentRoute;

    const faviconHref = ROUTE_FAVICONS[routeKey] || DEFAULT_FAVICON;

    const upsertFavicon = (rel: string) => {
      let link = document.querySelector(`link[rel="${rel}"]`) as HTMLLinkElement | null;
      if (!link) {
        link = document.createElement('link');
        link.setAttribute('rel', rel);
        document.head.appendChild(link);
      }
      link.setAttribute('type', 'image/svg+xml');
      link.setAttribute('href', faviconHref);
    };

    upsertFavicon('icon');
    upsertFavicon('alternate icon');
  }, [currentRoute]);

  // Handle hash-based routing
  useEffect(() => {
    const handleHashChange = () => {
      const hash = window.location.hash.slice(1) || 'dashboard';
      const parts = hash.split('/').map(decodeHashSegment);

      // Handle multi-segment routes like 'bulk-upload/status' or 'bulk-upload/new'
      // Format: #route/subpath/id or #route/id or #route
      let route = parts[0];
      let id = null;

      if (parts[0] === 'user-management' && parts.length === 3 && parts[2] === 'security') {
        route = 'user-management/security';
        id = parts[1];
      } else if (
        parts[0] === 'facilities'
        && parts[1] === 'new'
      ) {
        route = 'facilities/new';
      } else if (
        parts[0] === 'recruitment'
        && parts[1] === 'job-posts'
        && parts[2] === 'new'
      ) {
        route = 'recruitment/job-posts/new';
      } else if (
        parts[0] === 'recruitment'
        && parts[1] === 'job-posts'
        && parts[2] === 'edit'
        && parts.length >= 4
      ) {
        route = 'recruitment/job-posts/edit';
        id = parts.slice(3).join('/');
      } else if (parts[0] === 'recruitment' && parts[1] === 'job-posts' && parts.length >= 3) {
        route = 'recruitment/job-posts';
        id = parts.slice(2).join('/');
      } else if (parts.length === 3) {
        // e.g., #bulk-upload/status/JOB-001
        route = `${parts[0]}/${parts[1]}`;
        id = parts[2];
      } else if (parts.length === 2) {
        // Could be #bulk-upload/new or #licenses/LIC-001
        // Check if second part looks like an ID or is a subpath
        if (parts[0] === 'bulk-upload' && (parts[1] === 'new' || parts[1] === 'status')) {
          route = `${parts[0]}/${parts[1]}`;
        } else if (parts[0] === 'recruitment' && (parts[1] === 'job-posts' || parts[1] === 'candidates')) {
          route = `${parts[0]}/${parts[1]}`;
        } else if (parts[0] === 'user-management' && parts[1] === 'new') {
          route = 'user-management/new';
        } else if (parts[0] === 'user-management') {
          route = 'user-management';
          id = parts[1];
        } else {
          // Second part is an ID
          id = parts.slice(1).join('/');
        }
      }

      setCurrentRoute(route);
      setCurrentDetailId(id || null);
    };

    handleHashChange();
    window.addEventListener('hashchange', handleHashChange);
    return () => window.removeEventListener('hashchange', handleHashChange);
  }, []);

  const toggleTheme = () => {
    setIsDarkMode(!isDarkMode);
  };

  const navigateToRoute = useCallback((route: string, id?: string) => {
    const normalizedId = !id
      ? null
      : encodeHashId(id);

    const hash = normalizedId ? `#${route}/${normalizedId}` : `#${route}`;
    window.location.hash = hash;
    setCurrentRoute(route);
    setCurrentDetailId(id || null);
  }, []);

  // Route-level permission redirects:
  // - Missing permissions => force Company Permissions page (except standalone profile)
  // - Permissions restored while on Company Permissions page => send user to default entry route
  useEffect(() => {
    if (initializing || authLoading || !isAuthenticated) return;

    if (accessPolicy.mode !== 'none' && currentRoute === COMPANY_PERMISSION_ROUTE) {
      window.location.hash = `#${accessPolicy.defaultRoute}`;
      return;
    }

    if (!isRouteAllowed(currentRoute, accessPolicy)) {
      window.location.hash = `#${accessPolicy.defaultRoute}`;
      return;
    }
  }, [initializing, authLoading, isAuthenticated, accessPolicy, currentRoute]);

  // Enhanced theme configuration - Premium design
  const themeConfig = {
    algorithm: isDarkMode ? theme.darkAlgorithm : theme.defaultAlgorithm,
    token: {
      colorPrimary: '#1890ff',
      colorSuccess: '#52c41a',
      colorWarning: '#faad14',
      colorError: '#ff4d4f',
      colorInfo: '#1890ff',
      borderRadius: 8,
      borderRadiusLG: 12,
      borderRadiusXS: 4,
      fontFamily: 'Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif',
      fontSize: 12,
      fontSizeLG: 14,
      fontSizeXL: 16,
      lineHeight: 1.45,
      controlHeight: 28,
      controlHeightLG: 34,
      boxShadow: '0 2px 8px rgba(0, 0, 0, 0.06)',
      boxShadowSecondary: '0 4px 16px rgba(0, 0, 0, 0.08)',
      colorBgLayout: isDarkMode ? '#141414' : '#f5f7fa',
      colorBgContainer: isDarkMode ? '#1f1f1f' : '#ffffff',
      colorBgElevated: isDarkMode ? '#262626' : '#ffffff',
      colorBorder: isDarkMode ? '#303030' : '#e8e8e8',
      colorBorderSecondary: isDarkMode ? '#424242' : '#f0f0f0',
      colorText: isDarkMode ? '#ffffff' : '#262626',
      colorTextSecondary: isDarkMode ? '#a6a6a6' : '#595959',
      colorTextTertiary: isDarkMode ? '#737373' : '#8c8c8c',
    },
    components: {
      Layout: {
        headerBg: isDarkMode ? '#1f1f1f' : '#ffffff',
        bodyBg: isDarkMode ? '#141414' : '#f5f7fa',
        siderBg: isDarkMode ? '#1f1f1f' : '#ffffff',
      },
      Menu: {
        itemBg: 'transparent',
        itemSelectedBg: isDarkMode ? '#1890ff1a' : '#e6f4ff',
        itemHoverBg: isDarkMode ? '#262626' : '#f5f5f5',
        itemActiveBg: isDarkMode ? '#1890ff1a' : '#e6f4ff',
        subMenuItemBg: 'transparent',
        itemMarginBlock: 2,
        itemHeight: 34,
        itemFontSize: 12,
        itemBorderRadius: 8,
      },
      Card: {
        borderRadiusLG: 12,
        headerHeight: 42,
        headerFontSize: 14,
        bodyPadding: 14,
        boxShadowTertiary: '0 2px 8px rgba(0, 0, 0, 0.06)',
      },
      Button: {
        borderRadius: 8,
        borderRadiusLG: 10,
        borderRadiusSM: 6,
      },
      Input: {
        borderRadius: 8,
      },
      Table: {
        borderRadiusLG: 10,
        cellPaddingBlock: 10,
        cellPaddingInline: 12,
        cellFontSize: 13,
      },
      Progress: {
        circleTextFontSize: '1em',
      },
    },
  };

  // Render current page based on route
  const renderPage = () => {
    switch (currentRoute) {
      case 'dashboard':
        return (
          <ExecutiveDashboard
            navigateToRoute={navigateToRoute}
          />
        );

      case COMPANY_PERMISSION_ROUTE:
        return <CompanyPermissionRequired onNavigate={navigateToRoute} />;

      case 'health-professionals':
        return <EmployeeListView />;

      case 'assets':
        if (currentDetailId === 'new') {
          return <AssetCreateForm navigateToRoute={navigateToRoute} />;
        }
        if (currentDetailId) {
          return <AssetDetailView assetId={currentDetailId} navigateToRoute={navigateToRoute} />;
        }
        return <ERPNextAssetsListView navigateToRoute={navigateToRoute} />;

      case 'facilities':
        return <FacilitiesListView navigateToRoute={navigateToRoute} initialFacilityId={currentDetailId} />;

      case 'facilities/new':
        return <FacilityOnboardingWizard navigateToRoute={navigateToRoute} standalone={accessPolicy.mode === 'none'} />;

      // Shift Management (admin-only phase 1) + attendance visibility
      case 'attendance':
        return <ShiftManagementView initialTab="assignments" />;

      case 'late-arrivals':
        return <ShiftManagementView initialTab="attendance" forceLateOnly />;

      // eContracting route (Under Construction)
      case 'e-contracting':
        return (
          <div style={{ padding: '24px' }}>
            <Card style={{ borderRadius: 12, border: 'none', boxShadow: '0 2px 12px rgba(0,0,0,0.08)' }}>
              <EmptyState
                type="under-construction"
                title="eContracting"
                description="Digital contract management is being prepared."
                onAction={() => navigateToRoute('dashboard')}
                actionText="Return to Dashboard"
              />
            </Card>
          </div>
        );

      // Affiliations route
      case 'affiliations':
        return <AffiliationsListView />;

      case 'add-affiliation':
        return <SingleAffiliationPage navigateToRoute={navigateToRoute} />;

      // Bulk Upload routes
      case 'bulk-upload':
        // Check for nested routes
        if (currentDetailId === 'new') {
          // #bulk-upload/new - Create new upload wizard
          return <BulkUploadPage navigateToRoute={navigateToRoute} />;
        } else if (currentDetailId === 'status') {
          // This shouldn't happen as status needs a job ID
          // Fallback to list page
          return <BulkUploadListPage navigateToRoute={navigateToRoute} />;
        } else {
          // #bulk-upload - List all upload jobs
          return <BulkUploadListPage navigateToRoute={navigateToRoute} />;
        }

      case 'bulk-upload/new':
        // #bulk-upload/new - Create new upload wizard
        return <BulkUploadPage navigateToRoute={navigateToRoute} />;

      case 'bulk-upload/status':
        // #bulk-upload/status/{jobId} - View job status
        if (currentDetailId) {
          return <BulkUploadDetailView jobId={currentDetailId} navigateToRoute={navigateToRoute} />;
        }
        // No job ID provided, redirect to list
        return <BulkUploadListPage navigateToRoute={navigateToRoute} />;

      // Licenses route
      case 'licenses':
        if (currentDetailId) {
          return (
            <LicenseDetailView
              licenseId={currentDetailId}
              navigateToRoute={navigateToRoute}
            />
          );
        }
        return <LicensesListView navigateToRoute={navigateToRoute} />;

      // User Management routes
      case 'user-management':
        if (ENABLE_USER_MGMT_REFACTOR) {
          return <UserManagementPage navigateToRoute={navigateToRoute} selectedUserId={currentDetailId} />;
        }
        return <UserListPage navigateToRoute={navigateToRoute} />;

      case 'user-management/new':
        if (ENABLE_USER_MGMT_REFACTOR) {
          return <UserManagementPage navigateToRoute={navigateToRoute} viewMode="create" />;
        }
        return <CreateUserPage navigateToRoute={navigateToRoute} />;

      case 'user-management/security':
        if (ENABLE_USER_MGMT_REFACTOR) {
          return <UserManagementPage navigateToRoute={navigateToRoute} selectedUserId={currentDetailId} viewMode="security" />;
        }
        if (currentDetailId) {
          return <EditUserPage userId={currentDetailId} navigateToRoute={navigateToRoute} />;
        }
        return <UserListPage navigateToRoute={navigateToRoute} />;

      case 'oidc-apps':
        return <OidcAppsView />;

      // Legacy user management routes kept for gradual migration
      case 'create-user':
        return <CreateUserPage navigateToRoute={navigateToRoute} />;

      case 'edit-user':
        if (currentDetailId) {
          return <EditUserPage userId={currentDetailId} navigateToRoute={navigateToRoute} />;
        }
        return <UserListPage navigateToRoute={navigateToRoute} />;

      case 'profile':
        return <ProfilePage navigateToRoute={navigateToRoute} />;

      // HR: Leave Applications (Admin Central visibility for approvals)
      case 'leave-summary':
        return <LeaveApplicationsListView />;

      // Facility Claims (Claim Record – summary + paginated list)
      case 'claims':
        return <ClaimsListView />;

      // Recruitment Desk
      case 'recruitment':
        return <RecruitmentDeskPage key="recruitment-root" navigateToRoute={navigateToRoute} />;

      case 'recruitment/job-posts':
        return (
          <RecruitmentDeskPage
            key="recruitment-job-posts"
            navigateToRoute={navigateToRoute}
            initialTab="job-posts"
            selectedJobPostId={currentDetailId || undefined}
          />
        );

      case 'recruitment/job-posts/new':
        return <JobPostEditorPage mode="create" navigateToRoute={navigateToRoute} />;

      case 'recruitment/job-posts/edit':
        if (!currentDetailId) {
          return (
            <RecruitmentDeskPage
              key="recruitment-job-posts-edit-fallback"
              navigateToRoute={navigateToRoute}
              initialTab="job-posts"
            />
          );
        }
        return <JobPostEditorPage mode="edit" jobId={currentDetailId} navigateToRoute={navigateToRoute} />;

      case 'recruitment/candidates':
        if (currentDetailId) {
          // PRV-04: Candidate Profile detail
          return <CandidateProfileView candidateId={currentDetailId} navigateToRoute={navigateToRoute} />;
        }
        return <RecruitmentDeskPage key="recruitment-candidates" navigateToRoute={navigateToRoute} initialTab="pipeline" />;

      // Placeholder routes for modules under development
      case 'budget-overview':
      case 'account-balances':
      case 'financial-reports':
      case 'hr-reports':
      default:
        return (
          <div style={{ padding: '24px' }}>
            <Card style={{ borderRadius: 12, border: 'none', boxShadow: '0 2px 12px rgba(0,0,0,0.08)' }}>
              <EmptyState
                type="under-construction"
                title={`${currentRoute.split('-').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ')}`}
                description="This module is being prepared for you."
                onAction={() => navigateToRoute('dashboard')}
                actionText="Return to Dashboard"
              />
            </Card>
          </div>
        );
    }
  };

  // Show loading state while bootstrapping authentication and access mode.
  if (initializing || authLoading) {
    return (
      <ConfigProvider theme={themeConfig} locale={enUS}>
        <Layout className="auth-loading" style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          <Content style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', flexDirection: 'column', gap: '16px' }}>
            <Spin size="large" />
            <span style={{ color: 'rgba(255, 255, 255, 0.7)', fontSize: '13px', fontWeight: 500, letterSpacing: '0.3px' }}>
              {authLoading ? 'Verifying Session...' : 'Syncing Global Context...'}
            </span>
          </Content>
        </Layout>
      </ConfigProvider>
    );
  }

  // Show professional login page if not authenticated
  if (isAuthenticated === false) {
    return (
      <ConfigProvider theme={themeConfig} locale={enUS}>
        <UnauthorizedPage
          isDarkMode={isDarkMode}
          onToggleTheme={toggleTheme}
        />
      </ConfigProvider>
    );
  }

  if (isAuthenticated && accessPolicy.mode === 'none') {
    if (currentRoute === 'profile') {
      return (
        <ConfigProvider theme={themeConfig} locale={enUS}>
          <ProfilePage navigateToRoute={navigateToRoute} showStandaloneHeader />
        </ConfigProvider>
      );
    }

    if (ENABLE_FACILITY_ONBOARDING && currentRoute === 'facilities/new') {
      return (
        <ConfigProvider theme={themeConfig} locale={enUS}>
          <FacilityOnboardingWizard navigateToRoute={navigateToRoute} standalone />
        </ConfigProvider>
      );
    }

    return (
      <ConfigProvider theme={themeConfig} locale={enUS}>
        <CompanyPermissionRequired onNavigate={navigateToRoute} />
      </ConfigProvider>
    );
  }

  const page = renderPage();

  // Authenticated user with app access - render main app with layout
  return (
    <ConfigProvider theme={themeConfig} locale={enUS}>
      <AppLayout
        currentRoute={currentRoute}
        onNavigate={navigateToRoute}
        isDarkMode={isDarkMode}
        onToggleTheme={toggleTheme}
        accessPolicy={accessPolicy}
      >
        {page}
      </AppLayout>
    </ConfigProvider>
  );
}

export default App;
